    border-bottom-right-radius: 10px;
    transition: all 0.3s ease-in-out;
    border-top: none;
}

.sets-container.expanded {
    display: block;
}

.summary-sets-container {
    font-size: 12px;
    color: #8e8e93;
    padding: 0 16px 11px 35px;
    flex-wrap: wrap;
}

.summary-sets-container span {
    margin-right: 12px;
    white-space: nowrap;
}

.exercise-header:not(.expanded) + .summary-sets-container {
    display: flex;
}

.set-row {
    padding: 0px 86px 0px 69px;
    border-bottom: 0.5px solid #e5e5ea;
    font-size: 14px;
    display: flex;
    align-items: center;
}

.set-row.done {
    background-color: #d4edda;
    border-color: #96bfa0;
}

.main-set {
    color: #d93c3c;
    font-weight: 500;
}

.checkbox-wrapper {
    display: inline-flex;
    align-items: center;
    cursor: pointer;
    gap: 5px;
    margin-top: 10px;
}

.checkbox-input {
    display: none;
}

.checkbox-custom {
    width: 18px;
    height: 18px;
    border: 1px solid #c7c7cc;
    border-radius: 4px;
    position: relative;
}

.checkbox-input:checked + .checkbox-custom::after {
    content: '';
    position: absolute;
    width: 15px;
    height: 5px;
    border-left: 4px solid #009832;
    border-bottom: 3px solid #009832;
    top: 3px;
    left: 3px;
    transform: rotate(-45deg);
}

.checkbox-text {
    font-size: 14px;
    color: #1c1c1e;
}

.modal-set h3 {
    font-size: 17px;
}

