.modal-set, .modal-content {
    background-color: white;
    padding: 20px;
    border-radius: 12px;
    width: 90%;
    max-width: 400px;
    transform: scale(0.9);
    transition: transform 0.3s ease;
}

.modal-set {
    width: 283px;
}

.modal-set h3 {
    font-size: 17px;
    margin-left: 3px;
    padding-top: 12px;
}

.modal-set input[type="number"] {
    width: 52px;
    text-align: center;
    margin-left: 5px;
    margin-top: 2px;
}

.modal-set label {
    display: flex;
    margin-top: 7px;
    flex-direction: row;
}

.modal-set span {
    line-height: 1.5;
    margin-left: 4px;
}

.modal-set button.btn.btn-primary {
    width: 82px;
    margin-left: 18px;
    margin-bottom: 7px;
    padding: 9px 16px;
}

.modal-set button.btn.btn-primary:active {
    transform: scale(1.1);
    transition: transform 0.2s ease;
}

button.btn.delete-set-btn {
    background: none;
    color: #ed392f;
    width: 41px;
    height: 41px;
    padding: 0;
}

button.btn.delete-set-btn svg {
    display: block;
}

button.btn.delete-set-btn:active svg {
    transform: scale(1.3);
}

span.set-label {
    font-size: 13px;
}

span.set-display {
    margin-left: 15px;
    flex-grow: 1;
}

span.set-display small {
    margin-right: 6px;
}

small.unit-label {
    font-size: 12px;
    color: #606060;
}

.set-row:last-child {
    border-bottom: none;
}

.set-input-group {
    display: none;
    flex-grow: 1;
    gap: 4px;
    padding-left: 10px;
}

.set-input-group input {
    padding: 6px;
    text-align: center;
    max-width: 50px;
}

.set-row.editing .set-input-group {
    display: flex;
}

.set-row.editing .set-display {
    display: none;
}

.set-row .delete-set-row-btn {
    background: none;
    color: #b63c3c;
    width: 20px;
    height: 20px;
    font-size: 18px;
    line-height: 1;
    padding: 0;
}

.add-set-btn {
    color: #078bef;
    padding: 10px 0px 10px 0px;
    font-size: 22px;
    border: none;
    margin: 0px auto 0px 59px;
    width: 50%;
    display: flex;
    align-content: center;
    justify-content: center;
    align-items: center;
}

.add-set-btn:active svg {
    transform: scale(1.3);
