.modal-compact input {
    display: block;
    width: 91%;
    margin: 10px auto;
    text-align: center;
}

.modal-compact .h-wheel-label {
    font-weight: 600;
}

.h-wheel-wrapper {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 5px;
    margin: 10px 0 15px;
    width: 136px;
}

.h-wheel-arrow {
    background: none;
    border: none;
    font-size: 22px;
    cursor: pointer;
    color: #8b8b8b;
}

.h-wheel {
    display: flex;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    white-space: nowrap;
    width: 120px;
    height: 40px;
    align-items: center;
    position: relative;
    -webkit-overflow-scrolling: touch;
}

.h-wheel::-webkit-scrollbar {
    display: none;
}

.h-wheel-item {
    flex: 0 0 22px;
    height: 40px;
    line-height: 40px;
    text-align: center;
    scroll-snap-align: center;
    font-size: 18px;
    color: #999;
    opacity: 0.5;
    transition: 0.2s;
}

.h-wheel-item.active {
    font-weight: bold;
    color: #000;
    opacity: 1;
    transform: scale(1.1);
