    /* border-bottom: 1.5px solid #dedede; */
    height: 43px;
    margin-top: 5px;
    font-weight: 600;
    font-size: 12px;
    box-shadow: 0px 1px 3px #00000030!important;
    border: 0.5px solid #d9d9d9;
}

button.btn.btn-primary.add-exercise-btn:active {
    transition: transform 0.2s ease;
    box-shadow: none !important;
}

.modal-overlay.program-details .modal-content {
    display: flex;
    flex-direction: row;
    align-items: center;
}

.modal-overlay.program-details .modal-content .modal-buttons button {
    margin-left: 10px;
    padding: 9px 14px;
    border: 1.5px solid #268eff;
    background: none;
    color: #268eff;
}

.modal-overlay.program-details .modal-content .modal-buttons button:hover {
    transform: scale(1.1);
    background: #eff6ff;
}

