.checkbox-container {
    display: flex;
    align-items: center;
    cursor: pointer;
    font-size: 14px;
    position: relative;
    padding-left: 28px;
}

.checkbox-container input {
    position: absolute;
    opacity: 0;
    cursor: pointer;
}

.checkbox-container .checkmark {
    position: absolute;
    left: 0;
    top: 1px;
    height: 18px;
    width: 18px;
    border-radius: 4px;
    transition: 0.2s;
    background-color: #ffffff;
    border: 1px solid #b2b1b1;
}

.checkbox-container input:checked ~ .checkmark {
    background-color: #ffffff;
    border: 1px solid #b2b1b1;
}

.checkmark:after {
    content: "";
    position: absolute;
    display: none;
}

.checkbox-container input:checked ~ .checkmark:after {
    display: block;
}

.checkbox-container .checkmark:after {
    content: '';
    position: absolute;
    width: 15px;
    height: 5px;
    border-left: 4px solid #009832;
    border-bottom: 3px solid #009832;
    top: 3px;
    left: 3px;
