    top: 100%;
    left: 0;
    width: 100%;
    background: white;
    border-radius: 8px;
    overflow-y: auto;
    box-shadow: 0 4px 8px rgba(0,0,0,0.15);
    opacity: 0;
    pointer-events: none;
    transition: 0.2s ease;
    z-index: 10;
    max-height: 200px;
}

.select-options.open {
    opacity: 1;
    pointer-events: auto;
}

