.calendar-container {
    margin: 16px 0;
}

.calendar {
    display: flex;
    flex-direction: column;
    gap: 5px;
}

.calendar-row, .calendar-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
}

.calendar-cell {
    padding: 8px;
    text-align: center;
    border: 1px solid #ccc;
    min-height: 30px;
    cursor: default;
    font-size: 14px;
    border-radius: 4px;
}

.calendar-cell.has-training {
    background-color: #d4edda;
    cursor: pointer;
    font-weight: bold;
    border: 1px solid #96bfa0;
}

.calendar-cell.planned {
    background: #e9e9e9;
    border: 1px solid #c4c4c4;
}

.calendar-cell.header-cell {
    font-weight: bold;
    background-color: #fcc8aea8;
    height: 46px;
    min-height: 46px;
    display: flex;
    align-items: center;
    justify-content: space-around;
