    .modal-content.duplicate-modal {
        max-width: 300px;
        padding: 15px;
        border-radius: 10px;
        text-align: center;
        background: #ffffff;
    }

    .duplicate-text {
        font-size: 16px;
        margin-bottom: 15px;
    }

    .duplicate-controls {
        display: flex;
        justify-content: space-around;
        gap: 10px;
        flex-direction: row;
    }

    .duplicate-controls .btn {
        flex: 1;
        margin-left: 0 !important;
        padding: 7px 16px!important;
        border: 1.5px solid #535353;
        color: #414141;
    }

    .duplicate-controls .btn: active {
        transform: scale(1.06);
