        gap: 12px;
        padding: 12px;
        background: white;
        border-radius: 10px;
        box-shadow: 0 0 2px rgba(0,0,0,0.1);
        margin-bottom: 12px;
        position: relative;
    }

    .cycle-label-block {
        display: flex;
        align-items: center;
        gap: 8px;
        padding: 8px 12px;
        background: linear-gradient(135deg, #f0f7ff, #e8f0fe);
        border-radius: 8px;
        border-left: 3px solid #4a90d9;
        cursor: pointer;
        user-select: none;
        position: relative;
    }

    .cycle-label-icon {
        font-size: 18px;
        flex-shrink: 0;
    }

    .cycle-label-text {
        font-size: 15px;
        font-weight: 600;
        color: #1a3a5c;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        flex: 1;
    }

    .cycle-label-arrow {
        font-size: 14px;
        color: #4a90d9;
        transition: transform 0.2s ease;
        flex-shrink: 0;
    }

    .cycle-label-arrow.open {
        transform: rotate(180deg);
    }

    .active-filter-row {
        display: flex;
        align-items: center;
        gap: 6px;
        padding: 6px 12px;
        background: #f8f8f8;
        border-radius: 8px;
        user-select: none;
    }

    .active-filter-label {
        font-size: 12px;
        color: #aaa;
        flex-shrink: 0;
    }

    .active-filter-value {
        font-size: 13px;
        font-weight: 600;
        color: #4a90d9;
        background: rgba(74, 144, 217, 0.1);
        padding: 3px 10px;
        border-radius: 12px;
        white-space: nowrap;
        overflow: hidden;
        text-overflow: ellipsis;
        flex: 1;
    }

    .active-filter-value.all {
        color: #555;
        background: rgba(0, 0, 0, 0.05);
    }

    .filter-dropdown {
        position: absolute;
        bottom: 100%;
        left: 0;
        right: 0;
        background: #fff;
        border-radius: 10px;
        box-shadow: 0 -4px 16px rgba(0,0,0,0.12);
        padding: 12px;
        margin-bottom: 6px;
        display: flex;
        flex-direction: column;
        gap: 10px;
        opacity: 0;
        visibility: hidden;
        transform: translateY(8px);
        transition: opacity 0.2s ease, transform 0.2s ease, visibility 0.2s;
        z-index: 50;
    }

    .filter-dropdown.open {
        opacity: 1;
        visibility: visible;
        transform: translateY(0);
    }

    .filter-section-label {
        font-size: 13px;
        font-weight: 500;
        color: #888;
        text-transform: uppercase;
        letter-spacing: 0.5px;
    }

    .program-pills {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
    }

    .program-pill {
        padding: 6px 14px;
        border-radius: 20px;
        border: 1px solid #ddd;
        background: #f8f8f8;
        font-size: 13px;
        font-weight: 500;
        color: #555;
        cursor: pointer;
        transition: all 0.2s ease;
        white-space: nowrap;
    }

    .program-pill: active {
        transform: scale(0.96);
    }

    .program-pill.active {
        background: #4a90d9;
        color: #fff;
        border-color: #4a90d9;
        box-shadow: 0 2px 6px rgba(74, 144, 217, 0.3);
    }

    .filter-block {
        display: flex;
        flex-direction: column;
    }

    select.cycle-select, select.program-select {
        padding: 8px 12px;
        border-radius: 8px;
        border: 1px solid #ddd;
        font-size: 14px;
        background: #f8f8f8;
