    .category-filter {
        display: flex;
        flex-wrap: wrap;
        gap: 8px;
        margin-bottom: 16px;
        padding: 8px;
        background-color: white;
        border-radius: 10px;
        box-shadow: 0 0.5px 0 0 rgba(0, 0, 0, 0.05);
    }

    .filter-btn {
        padding: 6px 12px;
        background-color: #e5e5ea;
        color: #1c1c1e;
        border-radius: 8px;
        font-size: 14px;
    }

    .filter-btn.active {
        background-color: #007aff;
        color: white;
    }

    .journal-record {
        display: block;
        margin-bottom: 12px;
        border-radius: 10px;
        padding: 16px;
        border: none;
    }

    .journal-record: last-child {
        margin-bottom: 0;
    }

    .journal-header {
        display: flex;
        justify-content: space-between;
        align-items: center;
        margin-bottom: 8px;
    }

    .journal-header h4 {
        font-size: 13px;
        font-weight: 100;
        margin: 0;
    }

    .journal-program-name {
        font-size: 15px;
        margin-bottom: 12px;
        font-weight: 700;
    }

    .journal-exercise-row {
        display: flex;
        justify-content: space-between;
        padding: 6px 0;
        border-top: 0.5px solid #e5e5ea;
