    .record-header {
        display: flex;
        gap: 0px;
        font-size: 16px;
        font-weight: 600;
        margin-bottom: 10px;
        flex-direction: column;
    }

    .record-header .title-del {
        display: flex;
        flex-direction: row;
    }

    .record-header .title-del .record-name {
        font-size: 19px;
        border-bottom: 1px solid #000000;
        width: 71%;
        overflow-wrap: break-word;
        font-weight: 700;
        padding: 26px 0px 8px 5px;
        margin: 0;
        color: #1c1c1e;
        margin-bottom: 6px;
        overflow: hidden;
        text-overflow: ellipsis;
        -webkit-line-clamp: 1;
    }

    .menu-record button.btn.delete-record-btn {
        padding: 0 8px 4px 0px;
        display: flex;
        align-items: flex-end;
    }

    .menu-record button.btn.delete-record-btn svg {
        width: 19px;
        height: 19px;
        color: #cd3931;
    }

    .edit-date-btn {
        background: none;
        border: none;
        font-size: 18px;
        cursor: pointer;
    }

    .date-input {
        padding: 4px 6px;
        font-size: 14px;
    }

    .save-date-btn, .cancel-btn {
        margin-left: 6px;
        font-size: 14px;
        /* border: 1.5px solid #535353; */
        color: #212121;
    }

    .delete-record-btn {
        /* width: 100%; */
        /* margin-top: 20px; */
        /* background-color: #ff3b30; */
        /* color: white; */
        /* padding: 10px; */
        /* border-radius: 8px; */
    }

    .journal-record-details {
        background-color: #ffffff;
        border-radius: 12px;
        padding: 16px;
        box-shadow: 0 0.5px 2px rgba(0, 0, 0, 0.08);
        margin: 16px;
    }

    .menu-record {
        display: flex;
        flex-direction: row;
