    .training-comment-block {
        background: #f7f7f7;
        border-radius: 10px;
        padding: 11px 15px;
        margin-bottom: 5px;
        border-bottom: 1px solid #bababa;
        border: 0.5px solid #dedede;
    }

    .training-comment-block .comment-text {
        margin: 0 0 0px;
        font-size: 13px;
        color: #555;
        font-style: italic;
    }

    #journal-content .back-btn {
        font-size: 16px;
        background: none;
        border: none;
        cursor: pointer;
        color: #000000;
        padding: 1px 5px;
        margin-left: 1px;
        height: 28px;
        display: flex;
        align-items: center;
    }

    div#journal-content .record-header .date-edit {
        display: flex;
        flex-direction: row;
        align-items: center;
    }

    div#journal-content .record-header button.edit-date-btn {
        font-size: 0px;
        display: flex;
        align-items: flex-end;
    }

    div#journal-content .record-header button.edit-date-btn svg {
        color: #555;
    }

    div#journal-content .record-header .record-date {
        font-size: 12px;
        color: #555;
        p adding-left: 6px;
        padding-left: 11px;
        display: flex;
