    .mode-select-box {
        width: 100%;
        max-width: 400px;
        text-align: center;
    }

    .mode-select-box h3 {
        padding-top: 0;
        margin-bottom: 30px;
    }

    .mode-options {
        display: flex;
        flex-direction: column;
        gap: 15px;
        margin-bottom: 40px;
    }

    button#select-own-mode {
        padding: 4px 15px;
    }

    button#select-own-mode .mode-icon {
        margin-left: 15px;
        margin-right: 18px;
    }

    button#select-own-mode .mode-icon svg {
        width: 58px !important;
        height: 58px !important;
    }

    .mode-btn {
        display: flex;
        align-items: center;
        text-align: left;
        background-color: white;
        border-radius: 12px;
        padding: 22px 15px;
        width: 100%;
        cursor: pointer;
        /* border-bottom: 2.5px solid #e7e7e7; */
        /* border-left: 1px solid #e7e7e7; */
        /* border-top: 1px solid #e7e7e7; */
        /* border-right: 1px solid #e7e7e7; */
        box-shadow: 0 2px 0 #cccccc!important;
        border: 1px solid #e0e0e0;
    }

    .mode-btn: active {
        transition: transform 0.2s ease;
        box-shadow: none !important;
    }

    .mode-select-box button#mode-logout-btn {
        color: #535353;
        background: none;
        font-size: 15px;
        padding: 0;
        margin-left: 0;
    }

    #select-personal-mode .mode-icon {
        margin-right: 24px;
        margin-left: 27px;
    }

    button#select-personal-mode span.mode-icon svg {
        width: 39px;
        height: 22px;
    }

    .mode-btn h4 {
        font-size: 15px;
        font-weight: 600;
        margin: 0;
        color: #1c1c1e;
    }

    .mode-btn p {
        font-size: 12px;
        color: #8e8e93;
        margin: 2px 0 0 0;
