    .sup-name: hover {
        background: rgba(0, 0, 0, 0.05);
        border-radius: 6px;
    }

    .modal-backdrop {
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0,0,0,0.5);
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 1000;
    }

    .modal-window {
        background: #fff;
        padding: 20px;
        border-radius: 12px;
        min-width: 300px;
        text-align: center;
    }

    .modal-buttons {
        display: flex;
        /* margin-top: 20px; */
        align-content: space-around;
    }

    .modal-input {
        width: 90%;
        padding: 8px;
        font-size: 15px;
        border-radius: 8px;
        height: 21px;
    }

    .position-controls {
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 10px;
        margin-top: 15px;
    }

    .btn.small-btn {
        padding: 5px 8px;
        font-size: 14px;
    }

    .supplement-col, .dose-col {
        min-width: 50px;
        max-width: 50px;
        width: 50px;
        text-align: center;
    }

    .dose-input {
        width: 100%;
        box-sizing: border-box;
