    }

    .food-passport-row-energy {
        align-items: flex-start;
    }

    .food-passport-name {
        font-size: 14px;
        font-weight: 600;
        color: #111;
    }

    .food-passport-name-energy {
        line-height: 1.05;
    }

    .food-passport-value {
        font-size: 14px;
        font-weight: 600;
        color: #111;
    }

    .food-passport-bar-bottom {
        margin-top: 3px;
        margin-bottom: 0;
    }

    .recipe-steps-block .food-passport-row {
        align-items: flex-start;
    }

    .recipe-steps-block .recipe-step-text {
        text-align: right;
        white-space: pre-wrap;
        word-break: break-word;
        font-weight: 500;
        max-width: 72%;
    }

    .create-food .edit-meal-search-main-action {
        border-radius: 8px;
        margin: 0;
        padding: 0 12px 0px 0;
        color: #585858;
        border: none;
        background: none;
        font-size: 14px;
        display: flex;
        align-items: center;
        gap: 8px;
        justify-content: flex-end;
