        color: #4a90d9;
        transition: transform 0.2s ease;
        flex-shrink: 0;
        margin-left: 8px;
    }

    .add-program-dropdown-list {
        position: absolute;
        bottom: calc(100% + 4px);
        left: 0;
        right: 0;
        background: #fff;
        border-radius: 10px;
        box-shadow: 0 -4px 16px rgba(0,0,0,0.12);
        padding: 6px;
        display: flex;
        flex-direction: column;
        gap: 2px;
        max-height: 220px;
        overflow-y: auto;
        opacity: 0;
        visibility: hidden;
        transform: translateY(6px);
        transition: opacity 0.2s ease, transform 0.2s ease, visibility 0.2s;
        z-index: 60;
    }

    .add-program-dropdown-list.open {
        opacity: 1;
        visibility: visible;
        transform: translateY(0);
    }

    .add-program-dropdown-item {
        padding: 10px 12px;
        border-radius: 8px;
        font-size: 14px;
        color: #1c1c1e;
        cursor: pointer;
        transition: background 0.15s;
        -webkit-tap-highlight-color: transparent;
    }

    .add-program-dropdown-item: active, .add-program-dropdown-item.active {
        background: rgba(10, 132, 255, 0.1);
        color: #007aff;
        font-weight: 500;
    }

    .add-program-actions {
        display: flex;
        flex-direction: row;
        gap: 10px;
        margin-top: 18px;
    }

    .add-program-actions .btn {
        flex: 1;
        min-height: 44px;
        border-radius: 10px;
        font-weight: 600;
        font-size: 15px;
        cursor: pointer;
    }

    .add-program-cancel-btn {
        border: 1px solid #d1d1d6;
        background: #f5f5f7;
        color: #3a3a3c;
    }

    .add-program-confirm-btn {
        border: none;
        color: #fff;
        background: linear-gradient(180deg, #4da3ff, #007aff);
        box-shadow: 0 4px 12px rgba(0, 122, 255, 0.25);
        transition: opacity 0.2s;
    }

    .add-program-confirm-btn.disabled, .add-program-confirm-btn: disabled {
        opacity: 0.4;
        cursor: not-allowed;
    }

    /* Post-registration success */
    .post-registration-overlay {
        -webkit-backdrop-filter: blur(12px);
        backdrop-filter: blur(12px);
        background: rgba(15, 23, 42, 0.48);
        padding: 20px;
        box-sizing: border-box;
    }

    .post-registration-modal {
        max-width: 380px;
        width: 100%;
        margin: 0 auto;
        text-align: center;
        padding: 28px 24px 26px !important;
        border-radius: var(--ui-radius-lg) !important;
        border: 1px solid rgba(255, 255, 255, 0.75);
        box-shadow: var(--ui-shadow-elevated);
        animation: modalSheetIn 0.35s cubic-bezier(0.22, 1, 0.36, 1) both;
    }

    .post-registration-modal__title {
        margin: 0 0 10px;
        font-size: 1.35rem;
        font-weight: 700;
    }

    .post-registration-modal__text {
        margin: 0;
        line-height: 1.55;
        font-size: 14px;
    }

    .post-registration-modal__code-label {
        margin-top: 20px;
        font-weight: 700;
        font-size: 14px;
        letter-spacing: 0.02em;
        color: #48484a;
    }

    .post-registration-modal__code.public-user-code-host {
        margin-top: 10px;
        padding: 16px 14px;
        background: linear-gradient(180deg, #f8fafc, #eef2f7);
        border: 1px solid var(--ui-border);
        border-radius: var(--ui-radius-md);
    }

    .post-registration-modal__btn {
        width: 100%;
        margin-top: 12px !important;
        padding: 14px 16px !important;
        border-radius: var(--ui-radius-md) !important;
        font-weight: 600 !important;
    }

    .post-registration-modal__btn--primary {
        margin-top: 10px !important;
        border: none !important;
        color: #fff !important;
        background: linear-gradient(180deg, var(--ui-auth-accent-mid), var(--ui-auth-accent)) !important;
        box-shadow: 0 8px 22px var(--ui-auth-glow);
