.exercise-swipe .swipe-actions.right {
    position: absolute;
    top: 0;
    right: 0px;
    bottom: 0;
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: 8px;
    padding: 0 10px;
    background: #f0f0f0;
    z-index: 1;
    border-radius: 0px 10px 0 0;
}

.exercise-swipe svg {
    width: 27px;
    height: 27px;
    color: #535252;
}

button.action-btn.action-delete svg {
    width: 19px;
    height: 19px;
    color: #ffffff;
}

button.action-btn.action-delete:active svg {
    transform: scale(1.1);
