.exercise-swipe.open .swipe-content {
    cursor: default;
}

#programs-icon svg {
    width: 34px !important;
    height: 36px !important;
    margin-top: 5px;
    margin-left: 3px;
}

#journal-icon svg {
    width: 34px !important;
    height: 34px !important;
    margin-top: 0px;
}

#supplement-icon svg {
    width: 36px !important;
    height: 36px !important;
}

#reports-icon svg {
    width: 66% !important;
    height: 66% !important;
    margin-top: 5px;
    margin-left: 2px;
}

#meal-icon svg {
    width: 33px !important;
    height: 33px !important;
    margin-top: 0px;
}

.training-dropdown-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 10px;
    cursor: pointer;
    transition: background 0.2s;
}

.training-dropdown-item:hover {
    background: #f2f2f2;
}

.delete-plan-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 15px;
    color: #b70000;
    padding: 0 4px;
}

.delete-plan-btn:hover {
