    right: 0;
    background: #fff;
    border-bottom-left-radius: 10px;
    border-bottom-right-radius: 10px;
    box-shadow: 0 8px 22px rgba(0, 0, 0, 0.14);
    transform: translateY(-100%);
    transition: transform 0.26s ease;
    padding: 0px 24px 18px;
}

.meal-calendar-sheet.open {
    transform: translateY(0);
}

.meal-calendar-header {
    position: relative;
    display: flex;
    align-items: flex-end;
    justify-content: space-around;
    min-height: 44px;
    margin-bottom: 10px;
}

.meal-calendar-title {
    font-size: 18px;
    line-height: 1.1;
    font-weight: 700;
    text-transform: lowercase;
    color: #111;
}

.meal-calendar-close-btn {
    position: absolute;
    right: 0;
    top: 0;
    width: 42px;
    height: 42px;
    border: none;
    border-radius: 50%;
    background: #07122b;
    color: #fff;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    display: none;
}

.meal-calendar-weekdays {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    margin-top: 4px;
    margin-bottom: 4px;
}

.meal-calendar-weekday {
    text-align: center;
    font-size: 14px;
    font-weight: 700;
    color: #444;
    padding: 6px 0;
}

.meal-calendar-months-viewport {
    overflow: hidden;
    width: 100%;
    touch-action: pan-y;
}

.meal-calendar-months-track {
    display: flex;
    width: 100%;
    will-change: transform;
}

.meal-calendar-month-page {
    flex: 0 0 100%;
    width: 100%;
    min-width: 100%;
}

.meal-calendar-grid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 0px 0;
    padding-top: 0px;
}

.meal-calendar-day {
    appearance: none;
    border: none;
    background: transparent;
    width: 34px;
    height: 34px;
    margin: 0 auto;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    color: #151515;
    font-size: 14px;
    font-weight: 400;
    line-height: 1;
    padding: 0;
}

.meal-calendar-day {
    position: relative;
}

.meal-calendar-day.has-entry::after {
    content: '';
    position: absolute;
    bottom: 3px;
    left: 50%;
    transform: translateX(-50%);
    width: 4px;
    height: 4px;
    border-radius: 50%;
    background: #268eff;
}

.meal-calendar-day.is-outside.has-entry::after {
    display: none;
}

.meal-calendar-day.is-outside {
    color: #b8b8b8;
}

.meal-calendar-day.is-selected {
    color: #268eff;
    border: 1px solid #268eff;
}

.meal-calendar-day.is-today:not(.is-selected) {
    color: #268eff;
}

.meal-calendar-bottom {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    margin-top: 12px;
    padding-right: 18px;
}

.meal-calendar-today-btn {
    border: none;
    background: transparent;
    color: #268eff;
    font-size: 16px;
    font-weight: 500;
    padding: 0;
    cursor: pointer;
}

/* ===== WEEK STRIP ===== */
.week-strip-header {
    /* display: flex; */
    align-items: center;
    justify-content: space-between;
    margin: 6px 2px 12px;
    display: grid;
    grid-template-columns: 1fr 6fr 2fr;
    padding: 0 10px;
}

button#meal-calendar-btn {
    border: none;
    padding: 0;
    margin-left: 16px;
    color: #3e8ce1;
}

button#meal-calendar-btn svg {
    width: 23px;
    height: 23px;
}

.week-strip-title {
    font-size: 15px;
    font-weight: 400;
    color: #111827;
    text-transform: none;
    padding-left: 4px;
}

.week-strip-today-btn {
    border: none;
    background: none;
    font-size: 16px;
    font-weight: 500;
    padding: 0;
    margin: 0;
    padding-right: 8px;
    color: #3e8ce1;
}

.week-row {
    display: flex;
    gap: 0px;
    /* margin: 0px 0 0px; */
    justify-content: space-evenly;
    padding: 0 15px;
    margin-bottom: 14px;
}

.week-day-item {
    border: none;
    background: none;
    padding: 0;
    margin: 0;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 5px;
    flex: 1;
}

.week-day-circle {
    width: 30px;
    height: 30px;
    border-radius: 50%;
    border: 1px solid #9c9c9c;
    background: #fafafa;
    display: flex;
    align-items: center;
    justify-content: center;
    box-sizing: border-box;
    transition: 0.18s ease;
}

.week-day-check {
    font-size: 17px;
    line-height: 1;
    color: #6ba7ea;
    font-weight: 700;
    opacity: 0;
    transform: scale(0.9);
    transition: 0.18s ease;
}

.week-day-item.has-food .week-day-check {
    opacity: 1;
    transform: scale(1);
}

.week-day-name {
    font-size: 13px;
    color: #4c4c4c;
    font-weight: 200;
}

.week-day-item.active .week-day-circle {
    border: 1px solid #268eff57;
    background: #76b4f9;
}

.week-day-item.today:not(.active) .week-day-circle, .week-day-item.today .week-day-name {
    border-color: #268eff;
    color: #268eff;
}

.week-day-item.today:not(.active) .week-day-check {
    color: #268eff;
}

.week-day-item.active .week-day-circle .week-day-check {
    color: white;
}

.week-day-item:active .week-day-circle {
    transform: scale(0.96);
}

