.food-input-row {
    display: flex;
    gap: 15px;
    margin-top: 11px;
    align-items: center;
}

.food-input-icon {
    display: flex;
    color: #6b6b73;
    flex-direction: row;
    align-items: center;
}

.food-input-row .input {
    padding: 12px 14px;
    border: none;
    width: 72px;
}

button.food-meal-select-btn {
    padding: 11px 14px;
    border: 0.5px solid #d7d7dc;
    width: 126px;
    background-color: white;
    border-radius: 10px;
    font-size: 15px;
    color: #1c1c1e;
    -webkit-appearance: none;
}

.food-meal-dropdown {
    position: absolute;
    left: 0;
    right: 0;
    top: calc(100% + 6px);
    background: #fff;
    border-radius: 10px;
    box-shadow: 0 8px 24px rgba(0,0,0,0.12);
    z-index: 30;
    overflow: hidden;
    border: 1px solid #e1e1e1;
    flex-direction: column;
    align-items: flex-end;
}

.food-meal-dropdown-item {
    width: 100%;
    border: none;
    background: #fff;
    text-align: center;
    padding: 12px 23px 12px 23px;
    font-size: 15px;
    color: #111;
    cursor: pointer;
    border-bottom: 1px solid #e1e1e1;
}

.food-meal-dropdown-item:last-child {
    border-bottom: none;
}

.food-meal-dropdown-item:active {
    background: #f3f4f6;
}

button.food-inline-save-btn {
    border: 1px solid #111827;
    border-radius: 8px;
    padding: 10px 30px;
    margin-top: 15px;
    color: #111827;
    font-weight: 500;
    background: #9e9e9e;
    display: none;
}

.food-current-card {
    padding: 6px 21px 0px 55px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 4px;
    margin-top: 7px;
}

.food-current-ring-block {
    flex: 0 0 100px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.food-current-ring {
    position: relative;
    width: 99px;
    height: 99px;
}

.food-ring-svg {
    width: 100px;
    height: 100px;
    transform: rotate(-90deg);
}

.food-ring-bg {
    fill: none;
    stroke: #ececec;
    stroke-width: 6px;
}

.food-ring-segment {
    fill: none;
    stroke-width: 7px;
    \: round;
    \: all 0.3s ease;
}

.food-ring-carbs {
    stroke: #5cc2bd;
}

.food-ring-fat {
    stroke: #a165c6;
}

.food-ring-protein {
    stroke: #dfac53;
}

.food-ring-center {
    position: absolute;
    inset: 0;
    width: 80px;
    height: 80px;
    border-radius: 50%;
    /* background: #fff; */
    margin: auto;
    display: flex;
    flex-direction: column;
    justify-content: center;
    align-items: center;
}

.food-ring-kcal {
    font-size: 20px;
    line-height: 1;
    font-weight: 600;
    color: #111;
}

.food-ring-label {
    margin-top: 0px;
    font-size: 13px;
    color: #111;
}

.food-current-macros {
    flex: 1;
    display: flex;
    justify-content: space-between;
    gap: 0px;
}

.food-current-macro {
    flex: 1;
    text-align: center;
}

.food-current-percent {
    font-size: 15px;
    line-height: 1.1;
    font-weight: 500;
    margin-bottom: 7px;
}

.food-current-grams {
    font-size: 16px;
    line-height: 1.05;
    font-weight: 600;
    color: #111;
    margin-bottom: 6px;
}

.food-current-name {
    font-size: 14px;
