    color: #111;
}

.food-current-macro-carbs .food-current-percent {
    color: #37a088;
}

.food-current-macro-fat .food-current-percent {
    color: #6a1b9a;
}

.food-current-macro-protein .food-current-percent {
    color: #a65e00;
