/*============ bottom sheet==============*/
.copy-meal-sheet-overlay {
    position: fixed;
    inset: 0;
    background: rgba(0, 0, 0, 0);
    z-index: 10000;
    transition: background 0.24s ease;
}

.copy-meal-sheet-overlay.open {
    background: rgba(0, 0, 0, 0.35);
}

.copy-meal-sheet {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    background: #fff;
    border-top-left-radius: 10px;
    border-top-right-radius: 10px;
    box-shadow: 0 -8px 24px rgba(0, 0, 0, 0.16);
    transform: translateY(100%);
    transition: transform 0.24s ease;
    overflow: hidden;
}

.copy-meal-sheet.open {
    transform: translateY(0);
}

.copy-meal-sheet-header {
    height: 56px;
    display: grid;
    grid-template-columns: 56px 1fr 56px;
    align-items: center;
    border-bottom: 1px solid #ececec;
    background: #fff;
}

.copy-meal-sheet-close, .copy-meal-sheet-confirm {
    border: none;
    background: transparent;
    color: #111;
    width: 56px;
    height: 56px;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
}

.copy-meal-sheet-title {
    text-align: center;
    font-size: 15px;
    font-weight: 600;
    color: #111;
}

.copy-meal-sheet-wheels {
    position: relative;
    display: grid;
    grid-template-columns: 42% 58%;
    align-items: stretch;
    background: #fff;
    padding: 8px 48px 22px;
}

.copy-meal-sheet-selection-frame {
    position: absolute;
    left: 12px;
    right: 12px;
    top: calc(8px + 52px * 2);
    height: 52px;
    border-radius: 10px;
    background: #f2f2f7;
    pointer-events: none;
}

.copy-meal-sheet-col {
    position: relative;
    min-width: 0;
}

.copy-meal-sheet-wheel {
    overflow-y: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    scroll-snap-type: y mandatory;
    scrollbar-width: none;
}

.copy-meal-sheet-wheel::-webkit-scrollbar {
    display: none;
}

.copy-meal-sheet-spacer {
    flex-shrink: 0;
}

.copy-meal-sheet-item {
    width: 100%;
    border: none;
    background: transparent;
    scroll-snap-align: center;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 15px;
    line-height: 1;
    color: #b6b6bc;
    cursor: pointer;
    transition: color 0.18s ease, opacity 0.18s ease, transform 0.18s ease;
    padding: 0 12px;
    white-space: nowrap;
}

.copy-meal-sheet-item.active {
    color: #111;
}

.copy-meal-sheet-meal-item {
    font-weight: 500;
}

.copy-meal-sheet-day-item {
    font-weight: 500;
}

.copy-meal-sheet-col-left .copy-meal-sheet-item {
    justify-content: center;
}

.copy-meal-sheet-col-right .copy-meal-sheet-item {
    justify-content: center;
}

